// pages/UserProfile.tsx
import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { apiService } from '../services/api';
import './UserProfile.css';

const UserProfile: React.FC = () => {
  const { user } = useAuth();
  const [minioInfo, setMinioInfo] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [userFiles, setUserFiles] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'account' | 'files'>('account');
  const [debugInfo, setDebugInfo] = useState<string>('');

  useEffect(() => {
    const loadUserData = async () => {
      if (user) {
        try {
          console.log('🔄 [Profile] Loading user data...');
          setDebugInfo('Начинаю загрузку данных...\n');
          
          // Загружаем информацию о MinIO
          const info = await apiService.getUserMinioInfo();
          console.log('📦 [Profile] MinIO Info:', info);
          setMinioInfo(info);
          setDebugInfo(prev => prev + '✅ MinIO информация загружена\n');
          
          // Загружаем файлы основным методом
          console.log('📁 [Profile] Запрашиваю файлы пользователя...');
          setDebugInfo(prev => prev + '🔄 Загружаю файлы...\n');
          
          let files = await apiService.getUserFiles();
          console.log('📁 [Profile] Main method files:', files);
          
          // Если основной метод вернул пустой массив, пробуем альтернативный
          if (files.length === 0) {
            setDebugInfo(prev => prev + '⚠️ Основной метод вернул 0 файлов, пробую альтернативный...\n');
            files = await apiService.getUserFilesAlternative();
            console.log('📁 [Profile] Alternative method files:', files);
          }
          
          setDebugInfo(prev => prev + `✅ Загружено ${files.length} файлов\n`);
          setUserFiles(files);
          
        } catch (error: any) {
          console.error('❌ [Profile] Error loading user data:', error);
          setDebugInfo(prev => prev + `❌ Ошибка загрузки: ${error.message || JSON.stringify(error)}\n`);
          
          // Покажем тестовые данные для отладки
          setUserFiles([
            {
              name: 'test-image-1.jpg',
              url: 'https://via.placeholder.com/300x200/667eea/ffffff?text=Test+1',
              size: 102400,
              last_modified: new Date().toISOString(),
              type: 'image/jpeg',
              object_name: 'test-bucket/test-image-1.jpg'
            },
            {
              name: 'test-image-2.png',
              url: 'https://via.placeholder.com/300x200/764ba2/ffffff?text=Test+2',
              size: 204800,
              last_modified: new Date(Date.now() - 86400000).toISOString(),
              type: 'image/png',
              object_name: 'test-bucket/test-image-2.png'
            }
          ]);
          setDebugInfo(prev => prev + '⚠️ Использую тестовые данные\n');
        } finally {
          setLoading(false);
          setDebugInfo(prev => prev + '✅ Загрузка завершена\n');
        }
      }
    };

    loadUserData();
  }, [user]);

  const handleRefreshFiles = async () => {
    setLoading(true);
    setDebugInfo('🔄 Принудительная перезагрузка файлов...\n');
    
    try {
      let files = await apiService.getUserFiles();
      
      if (files.length === 0) {
        files = await apiService.getUserFilesAlternative();
      }
      
      setUserFiles(files);
      setDebugInfo(prev => prev + `✅ Загружено ${files.length} файлов\n`);
    } catch (error: any) {
      console.error('❌ Error refreshing files:', error);
      setDebugInfo(prev => prev + `❌ Ошибка: ${error.message || error}\n`);
    } finally {
      setLoading(false);
    }
  };

  const runDebugTests = async () => {
    setDebugInfo('🧪 Запуск отладки endpoint\'ов...\n');
    await apiService.debugEndpoints();
    setDebugInfo(prev => prev + '✅ Отладка завершена (см. консоль браузера)\n');
  };

  const testFilesEndpoint = async () => {
    setDebugInfo('🧪 Тестирую endpoint /files...\n');
    await apiService.testFilesEndpoint();
    setDebugInfo(prev => prev + '✅ Тест завершен (см. консоль)\n');
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString('ru-RU', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleDownload = async (url: string, filename: string) => {
    try {
      await apiService.downloadFile(url, filename);
    } catch (error) {
      console.error('Error downloading file:', error);
      alert('Ошибка при скачивании файла');
    }
  };

  const testFileDownload = async (objectName: string) => {
    setDebugInfo(prev => prev + `🧪 Тестирую скачивание: ${objectName}\n`);
    await apiService.testFileDownload(objectName);
    setDebugInfo(prev => prev + '✅ Тест завершен (см. консоль)\n');
  };

  if (!user) {
    return (
      <div className="profile-container">
        <div className="profile-card">
          <h2>⚠️ Доступ запрещен</h2>
          <p>Для просмотра профиля необходимо <a href="/login">войти в систему</a></p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="profile-container">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Загрузка профиля...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="user-profile">
      <div className="profile-header">
        <h1>👤 Профиль пользователя</h1>
        <div className={`user-badge ${user.is_admin ? 'admin' : 'user'}`}>
          {user.is_admin ? '👑 Администратор' : '👤 Пользователь'}
        </div>
      </div>

      {/* Debug section */}
      <div className="debug-section">
        <details>
          <summary>🛠️ Информация для отладки</summary>
          <div className="debug-controls">
            <button onClick={runDebugTests} className="debug-button">
              🐛 Debug All Endpoints
            </button>
            <button onClick={testFilesEndpoint} className="debug-button">
              🧪 Test /files Endpoint
            </button>
            <button onClick={handleRefreshFiles} className="debug-button">
              🔄 Перезагрузить файлы
            </button>
          </div>
          <pre className="debug-info">
            {debugInfo}
            {'---\n'}
            Пользователь: {user.username} {user.is_admin ? '(Admin)' : ''}
            {'\nФайлов в состоянии: '}{userFiles.length}
            {'\nMinIO подключен: '}{minioInfo ? 'Да' : 'Нет'}
            {'\nПапка пользователя: '}{minioInfo?.user_folder || 'Неизвестно'}
          </pre>
        </details>
      </div>

      <div className="profile-tabs">
        <button 
          className={`tab-button ${activeTab === 'account' ? 'active' : ''}`}
          onClick={() => setActiveTab('account')}
        >
          📋 Информация аккаунта
        </button>
        <button 
          className={`tab-button ${activeTab === 'files' ? 'active' : ''}`}
          onClick={() => setActiveTab('files')}
        >
          📁 История файлов ({userFiles.length})
        </button>
      </div>

      {activeTab === 'account' ? (
        <div className="profile-grid">
          <div className="profile-card">
            <h2>📋 Информация аккаунта</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Имя пользователя:</span>
                <span className="info-value">{user.username}</span>
              </div>
              
              {user.email && (
                <div className="info-item">
                  <span className="info-label">Email:</span>
                  <span className="info-value">{user.email}</span>
                </div>
              )}
              
              {user.created_at && (
                <div className="info-item">
                  <span className="info-label">Дата регистрации:</span>
                  <span className="info-value">{formatDate(user.created_at)}</span>
                </div>
              )}
              
              <div className="info-item">
                <span className="info-label">Статус:</span>
                <span className="status-badge active">Активен</span>
              </div>
              
              {minioInfo && (
                <>
                  <div className="info-item">
                    <span className="info-label">Хранилище:</span>
                    <span className="info-value storage-badge">{minioInfo.provider || 'MinIO'}</span>
                  </div>
                  
                  {minioInfo.user_folder && (
                    <div className="info-item">
                      <span className="info-label">Папка в MinIO:</span>
                      <span className="info-value code">{minioInfo.user_folder}</span>
                    </div>
                  )}
                  
                  {minioInfo.files_bucket && (
                    <div className="info-item">
                      <span className="info-label">Бакет:</span>
                      <span className="info-value">{minioInfo.files_bucket}</span>
                    </div>
                  )}
                  
                  {minioInfo.storage_used && (
                    <div className="info-item">
                      <span className="info-label">Использовано:</span>
                      <span className="info-value">{minioInfo.storage_used}</span>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>

          <div className="profile-card">
            <h2>⚙️ Системная информация</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Система цензурирования:</span>
                <span className="info-value">AI Face Detection</span>
              </div>
              
              <div className="info-item">
                <span className="info-label">Методы цензурирования:</span>
                <span className="info-value">Размытие, Пикселизация</span>
              </div>
              
              <div className="info-item">
                <span className="info-label">Поддерживаемые форматы:</span>
                <span className="info-value">JPG, PNG, GIF, BMP</span>
              </div>
              
              <div className="info-item">
                <span className="info-label">Максимальный размер файла:</span>
                <span className="info-value">10 MB</span>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="files-section">
          <div className="files-header">
            <div className="header-title">
              <h2>📁 История файлов</h2>
              <span className="files-count">{userFiles.length} файлов</span>
            </div>
            <div className="header-actions">
              <button 
                onClick={handleRefreshFiles}
                className="refresh-button"
                disabled={loading}
              >
                {loading ? '🔄 Обновление...' : '🔄 Обновить файлы'}
              </button>
            </div>
          </div>

          {userFiles.length === 0 ? (
            <div className="empty-files">
              <div className="empty-icon">📭</div>
              <h3>Файлы не найдены</h3>
              <p>У вас пока нет загруженных файлов в системе</p>
              <p className="debug-hint">
                <small>
                  ⚠️ Если вы загружали файлы через редактор, но они здесь не отображаются, 
                  возможно бэкенд не предоставляет endpoint для получения списка файлов.
                </small>
              </p>
              <div className="empty-actions">
                <a href="/redaction" className="upload-link">
                  🖼️ Перейти в редактор
                </a>
                <button 
                  onClick={() => setUserFiles([
                    {
                      name: 'demo-image.jpg',
                      url: 'https://via.placeholder.com/400x300/667eea/ffffff?text=Demo+Image',
                      size: 153600,
                      last_modified: new Date().toISOString(),
                      type: 'image/jpeg',
                      object_name: 'demo-bucket/demo-image.jpg'
                    }
                  ])}
                  className="demo-button"
                >
                  🧪 Показать демо
                </button>
              </div>
            </div>
          ) : (
            <>
              <div className="files-grid">
                {userFiles.map((file, index) => (
                  <div key={index} className="file-card">
                    <div className="file-preview">
                      {file.url && file.url.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i) ? (
                        <img 
                          src={file.url} 
                          alt={file.name} 
                          className="file-image"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display = 'none';
                            const parent = e.currentTarget.parentElement;
                            if (parent) {
                              const fallback = document.createElement('div');
                              fallback.className = 'file-icon';
                              fallback.textContent = '📄';
                              parent.appendChild(fallback);
                            }
                          }}
                          loading="lazy"
                        />
                      ) : (
                        <div className="file-icon">
                          {file.name?.match(/\.(pdf)$/i) ? '📄' : 
                           file.name?.match(/\.(doc|docx)$/i) ? '📝' : 
                           file.name?.match(/\.(xls|xlsx)$/i) ? '📊' : 
                           '📁'}
                        </div>
                      )}
                    </div>
                    
                    <div className="file-info">
                      <div className="file-name" title={file.name}>
                        {file.name || 'Без названия'}
                      </div>
                      
                      <div className="file-details">
                        {file.size !== undefined && (
                          <span className="file-size">📦 {formatFileSize(file.size)}</span>
                        )}
                        
                        {file.last_modified && (
                          <span className="file-date">📅 {formatDate(file.last_modified)}</span>
                        )}
                        
                        {file.type && (
                          <span className="file-type">🎯 {file.type}</span>
                        )}
                      </div>
                      
                      {file.object_name && (
                        <div className="file-object" title="Object name в MinIO">
                          🏷️ {file.object_name.length > 30 ? 
                            file.object_name.substring(0, 30) + '...' : 
                            file.object_name}
                        </div>
                      )}
                    </div>
                    
                    <div className="file-actions">
                      {file.url && (
                        <a 
                          href={file.url} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="action-button view"
                          title="Просмотреть"
                        >
                          👁️
                        </a>
                      )}
                      
                      <button 
                        onClick={() => handleDownload(file.url, file.name)}
                        className="action-button download"
                        title="Скачать"
                      >
                        ⬇️
                      </button>
                      
                      {file.url && (
                        <button 
                          onClick={() => {
                            navigator.clipboard.writeText(file.url);
                            alert('Ссылка скопирована в буфер обмена');
                          }}
                          className="action-button copy"
                          title="Копировать ссылку"
                        >
                          📋
                        </button>
                      )}
                      
                      {file.object_name && (
                        <button 
                          onClick={() => testFileDownload(file.object_name)}
                          className="action-button test"
                          title="Тест скачивания"
                        >
                          🧪
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
              
              {userFiles.some(file => file.url && file.url.includes('placeholder.com')) && (
                <div className="demo-warning">
                  ⚠️ Отображаются демо-данные. Реальные файлы из MinIO не загружены.
                  Проверьте консоль браузера для отладки.
                </div>
              )}
            </>
          )}

          {minioInfo && (
            <div className="storage-info">
              <h3>💾 Информация о хранилище</h3>
              <div className="storage-details">
                <div className="storage-item">
                  <span className="storage-label">Провайдер:</span>
                  <span className="storage-value">{minioInfo.provider || 'MinIO'}</span>
                </div>
                
                {minioInfo.files_bucket && (
                  <div className="storage-item">
                    <span className="storage-label">Бакет:</span>
                    <span className="storage-value">{minioInfo.files_bucket}</span>
                  </div>
                )}
                
                {minioInfo.user_folder && (
                  <div className="storage-item">
                    <span className="storage-label">Папка пользователя:</span>
                    <span className="storage-value code">{minioInfo.user_folder}</span>
                  </div>
                )}
                
                <div className="storage-item">
                  <span className="storage-label">Всего файлов:</span>
                  <span className="storage-value">{userFiles.length}</span>
                </div>
                
                {minioInfo.storage_used && (
                  <div className="storage-item">
                    <span className="storage-label">Использовано:</span>
                    <span className="storage-value">{minioInfo.storage_used}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default UserProfile;
